changeSet.sql:
CREATE OR REPLACE TRIGGER trg_incidencia_ciclo_vida
BEFORE INSERT OR UPDATE ON incidencia
FOR EACH ROW
DECLARE
    -- Centinela para comparar marcas que pueden ser NULL: convierte el NULL en un valor
    -- comparable, de modo que "poner a NULL una marca sellada" cuenta como modificacion.
    c_centinela CONSTANT TIMESTAMP(6) := TIMESTAMP '0001-01-01 00:00:00';
    -- Instante UNICO contra el que se valida la fila entera (coherencia dentro de la misma fila).
    l_ahora     TIMESTAMP(6) := SYS_EXTRACT_UTC(SYSTIMESTAMP);
BEGIN
    -- (1) Marcas selladas: una vez escritas no admiten modificacion ni borrado.
    IF UPDATING THEN
        IF :OLD.in_progress_at IS NOT NULL
           AND NVL(:NEW.in_progress_at, c_centinela) <> NVL(:OLD.in_progress_at, c_centinela) THEN
            RAISE_APPLICATION_ERROR(-20050, 'La marca de inicio de atención ya está sellada y no admite modificación');
        END IF;

        IF :OLD.resolved_at IS NOT NULL
           AND NVL(:NEW.resolved_at, c_centinela) <> NVL(:OLD.resolved_at, c_centinela) THEN
            RAISE_APPLICATION_ERROR(-20051, 'La marca de resolución ya está sellada y no admite modificación');
        END IF;

        IF :OLD.assigned_at IS NOT NULL
           AND NVL(:NEW.assigned_at, c_centinela) <> NVL(:OLD.assigned_at, c_centinela) THEN
            RAISE_APPLICATION_ERROR(-20052, 'La marca de asignación ya está sellada y no admite modificación');
        END IF;
    END IF;

    -- (2) Red de seguridad de AC-ASG-01: si la sentencia deja tecnico asignado sin marca de
    --     asignacion, la sella el motor con el instante del servidor. Solo actua con la marca
    --     vacia; una marca ya sellada la protege el bloque (1), que rechaza reescribirla.
    IF :NEW.assigned_technician_id IS NOT NULL AND :NEW.assigned_at IS NULL THEN
        :NEW.assigned_at := l_ahora;
    END IF;

    -- (3) Ninguna marca temporal del ciclo de vida puede ser futura.
    IF (:NEW.created_at        IS NOT NULL AND :NEW.created_at        > l_ahora)
    OR (:NEW.in_progress_at    IS NOT NULL AND :NEW.in_progress_at    > l_ahora)
    OR (:NEW.resolved_at       IS NOT NULL AND :NEW.resolved_at       > l_ahora)
    OR (:NEW.closed_at         IS NOT NULL AND :NEW.closed_at         > l_ahora)
    OR (:NEW.status_changed_at IS NOT NULL AND :NEW.status_changed_at > l_ahora)
    OR (:NEW.assigned_at       IS NOT NULL AND :NEW.assigned_at       > l_ahora)
    OR (:NEW.released_at       IS NOT NULL AND :NEW.released_at       > l_ahora) THEN
        RAISE_APPLICATION_ERROR(-20053, 'Una marca temporal del ciclo de vida no puede ser futura');
    END IF;

    -- (4) Comentario de resolucion: obligatorio al cerrar y prohibido fuera del cierre.
    --     REGEXP_INSTR recorre el CLOB completo sin truncarlo y devuelve 0 si no hay
    --     ningun caracter distinto de espacio (equivalente al "no vacio tras TRIM").
    IF :NEW.status = 'CERRADA' THEN
        IF :NEW.resolution_comment IS NULL
           OR DBMS_LOB.GETLENGTH(:NEW.resolution_comment) = 0
           OR NVL(REGEXP_INSTR(:NEW.resolution_comment, '[^[:space:]]'), 0) = 0 THEN
            RAISE_APPLICATION_ERROR(-20054, 'Debe indicar un comentario de resolución para cerrar la incidencia');
        END IF;
    ELSIF :NEW.resolution_comment IS NOT NULL THEN
        RAISE_APPLICATION_ERROR(-20055, 'El comentario de resolución solo existe en una incidencia cerrada');
    END IF;

    -- (5) Concurrencia optimista: version la lleva el motor, nunca la sentencia.
    --     Va al final para no incrementarla en escrituras que las reglas anteriores rechazan.
    IF UPDATING THEN
        :NEW.version := NVL(:OLD.version, 0) + 1;
    END IF;
END;

DECLARE
    v_admin       NUMBER;
    v_empleado    NUMBER;
    v_tec_a       NUMBER;
    v_tec_b       NUMBER;
    v_office      NUMBER;
    v_room        NUMBER;
    v_cat         NUMBER;
    v_inc         NUMBER;
    v_ultima      NUMBER;
    v_filas_a     NUMBER;
    v_filas_b     NUMBER;
    v_ganadores   NUMBER := 0;
    v_codigo      NUMBER;
    v_tecnico     incidencia.assigned_technician_id%TYPE;
    v_asignado_en incidencia.assigned_at%TYPE;
    v_status      incidencia.status%TYPE;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, 'N', 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');

        -- La categoria tiene que estar ACTIVA aunque la fila ya existiese: el trigger
        -- trg_incidencia_clasificacion rechaza el alta sobre catalogo inactivo (REQ-100).
        UPDATE cat_categoria_incidencia SET is_active = 'Y' WHERE category_code = p_code;
    END sembrar_categoria;

    -- SEGUNDA CONEXION sobre la incidencia ganadora. La transaccion autonoma es independiente
    -- de la principal: ni ve sus cambios sin confirmar ni comparte sus bloqueos. Devuelve el
    -- SQLCODE obtenido (0 si pudo tomar la fila, que es justo lo que no debe ocurrir) y hace
    -- ROLLBACK SIEMPRE antes de salir, porque una transaccion autonoma que termina sin cerrarse
    -- (sin confirmar ni deshacer) provoca ORA-06519. Aqui solo se deshace: nada se confirma.
    FUNCTION tomar_en_otra_transaccion(p_inc NUMBER) RETURN NUMBER IS
        PRAGMA AUTONOMOUS_TRANSACTION;
        l_tecnico NUMBER;
        l_codigo  NUMBER;
    BEGIN
        SELECT assigned_technician_id
          INTO l_tecnico
          FROM incidencia
         WHERE incident_id = p_inc
           FOR UPDATE NOWAIT;
        l_codigo := 0;
        ROLLBACK;
        RETURN l_codigo;
    EXCEPTION
        WHEN OTHERS THEN
            l_codigo := SQLCODE;
            ROLLBACK;
            RETURN l_codigo;
    END tomar_en_otra_transaccion;

BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 901);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 902);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 903);
    sembrar_estado('ABIERTA', 'Abierta', 901);
    sembrar_categoria('MOBILIARIO', 'Mobiliario oraculo concurrencia', 901);

    SELECT category_id INTO v_cat FROM cat_categoria_incidencia WHERE category_code = 'MOBILIARIO';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA54A' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA54A', 'Oficina Oraculo Concurrencia', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA54A';

    -- Los usuarios se crean ANTES que la sala porque cat_sala.created_by es NOT NULL.
    -- username, password_hash y password_algorithm son NOT NULL desde 06-usuario-credenciales.xml.
    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES ('Oraculo Concurrencia Admin', 'oraculo.tsk054.conc.admin@example.invalid',
                 'oraculo.tsk054.conc.admin', 'ADMINISTRADOR', 'ACTIVO',
                 'hash-oraculo-tsk054-admin', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Concurrencia Empleado', 'oraculo.tsk054.conc.empleado@example.invalid',
                 'oraculo.tsk054.conc.empleado', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk054-empleado', 'argon2id', v_admin)
      RETURNING user_id INTO v_empleado;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Concurrencia Tecnico A', 'oraculo.tsk054.conc.tecnico.a@example.invalid',
                 'oraculo.tsk054.conc.tecnico.a', 'TECNICO_MANTENIMIENTO', 'ACTIVO',
                 'hash-oraculo-tsk054-tecnico-a', 'argon2id', v_admin)
      RETURNING user_id INTO v_tec_a;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Concurrencia Tecnico B', 'oraculo.tsk054.conc.tecnico.b@example.invalid',
                 'oraculo.tsk054.conc.tecnico.b', 'TECNICO_MANTENIMIENTO', 'ACTIVO',
                 'hash-oraculo-tsk054-tecnico-b', 'argon2id', v_admin)
      RETURNING user_id INTO v_tec_b;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA54A' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA54A', 'Sala Oraculo Concurrencia', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA54A';

    -- 100 tomas en disputa de 100 incidencias distintas: en cada una, dos tecnicos emiten la
    -- MISMA sentencia condicional de REQ-153 y solo uno puede ganar.
    FOR i IN 1 .. 100 LOOP
        INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
             VALUES ('INC-9054-' || LPAD(i, 6, '0'), v_room, v_cat,
                     'Toma concurrente numero ' || i || ' del oraculo de asignacion de incidencias',
                     v_empleado)
          RETURNING incident_id INTO v_inc;

        -- Conexion 1 (tecnico A): sentencia canonica de autoasignacion de AC-ASG-02.
        UPDATE incidencia
           SET assigned_technician_id = v_tec_a
         WHERE incident_id = v_inc
           AND assigned_technician_id IS NULL;
        v_filas_a := SQL%ROWCOUNT;

        -- Conexion 2 (tecnico B): exactamente la misma sentencia sobre la misma incidencia.
        UPDATE incidencia
           SET assigned_technician_id = v_tec_b
         WHERE incident_id = v_inc
           AND assigned_technician_id IS NULL;
        v_filas_b := SQL%ROWCOUNT;

        IF v_filas_a <> 1 THEN
            RAISE_APPLICATION_ERROR(-20940, 'ORACULO AC-ASG-02 iteracion ' || i ||
                ': la primera toma afecto a ' || v_filas_a || ' filas en lugar de 1');
        END IF;

        IF v_filas_b <> 0 THEN
            RAISE_APPLICATION_ERROR(-20941, 'ORACULO AC-ASG-02 iteracion ' || i ||
                ': la segunda toma afecto a ' || v_filas_b ||
                ' filas en lugar de 0: la incidencia admite doble asignacion');
        END IF;

        SELECT assigned_technician_id, assigned_at, status
          INTO v_tecnico, v_asignado_en, v_status
          FROM incidencia
         WHERE incident_id = v_inc;

        IF v_tecnico IS NULL OR v_tecnico <> v_tec_a OR v_tecnico = v_tec_b THEN
            RAISE_APPLICATION_ERROR(-20942, 'ORACULO AC-ASG-02 iteracion ' || i ||
                ': el responsable de la incidencia es ' || NVL(TO_CHAR(v_tecnico), 'NULL') ||
                ' y deberia ser el tecnico ganador ' || v_tec_a);
        END IF;

        IF v_asignado_en IS NULL THEN
            RAISE_APPLICATION_ERROR(-20943, 'ORACULO AC-ASG-01 iteracion ' || i ||
                ': la toma no ha sellado assigned_at con el instante del servidor');
        END IF;

        IF v_status <> 'ABIERTA' THEN
            RAISE_APPLICATION_ERROR(-20944, 'ORACULO REQ-153 RN-06 iteracion ' || i ||
                ': la asignacion ha cambiado el estado a ' || v_status || ' en lugar de dejarlo en ABIERTA');
        END IF;

        v_ganadores := v_ganadores + 1;
        v_ultima := v_inc;
    END LOOP;

    IF v_ganadores <> 100 THEN
        RAISE_APPLICATION_ERROR(-20945, 'ORACULO AC-ASG-02: se han contado ' || v_ganadores ||
            ' tomas ganadoras en lugar de 100');
    END IF;

    -- Bloqueo de fila entre transacciones DISTINTAS: la ultima incidencia, tomada por el tecnico A
    -- y todavia SIN CONFIRMAR, es intocable desde otra transaccion. ORA-01403 (100) porque la fila
    -- sin confirmar no existe para ella; ORA-00054 (-54) si llegase a verla y no pudiese bloquearla.
    -- Lo que NUNCA puede devolver es 0, que significaria que otra transaccion la ha arrebatado.
    v_codigo := tomar_en_otra_transaccion(v_ultima);
    IF v_codigo NOT IN (-54, 100) THEN
        RAISE_APPLICATION_ERROR(-20946, 'ORACULO AC-ASG-02: una transaccion ajena obtuvo ' || v_codigo ||
            ' sobre la incidencia tomada y sin confirmar; mientras la ganadora no confirma ninguna' ||
            ' transaccion ajena puede arrebatar la fila, solo cabe ORA-01403 (100) u ORA-00054 (-54)');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin        NUMBER;
    v_empleado     NUMBER;
    v_tecnico      NUMBER;
    v_office       NUMBER;
    v_room         NUMBER;
    v_cat          NUMBER;
    v_inc          NUMBER;
    v_inc_c        NUMBER;
    v_version_alta NUMBER;
    v_version_res  NUMBER;
    v_codigo       NUMBER;
    v_status       incidencia.status%TYPE;
    v_closed_at    incidencia.closed_at%TYPE;
    v_resolved_at  incidencia.resolved_at%TYPE;
    v_closed_by    incidencia.closed_by%TYPE;
    v_closed_virt  NUMBER;
    v_comentario   CLOB;
    v_util         NUMBER;
    v_ahora        TIMESTAMP(6) := SYS_EXTRACT_UTC(SYSTIMESTAMP);

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    -- Variante del sembrador de estados con el flag is_terminal: este escenario necesita CERRADA,
    -- que es el unico estado terminal del catalogo (los demas se siembran con 'N').
    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER,
                             p_terminal VARCHAR2 DEFAULT 'N') IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, p_terminal, 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');

        -- La categoria tiene que estar ACTIVA aunque la fila ya existiese: el trigger
        -- trg_incidencia_clasificacion rechaza el alta sobre catalogo inactivo (REQ-100).
        UPDATE cat_categoria_incidencia SET is_active = 'Y' WHERE category_code = p_code;
    END sembrar_categoria;

BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 905);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 906);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 907);
    sembrar_estado('ABIERTA', 'Abierta', 905, 'N');
    sembrar_estado('RESUELTA', 'Resuelta', 906, 'N');
    sembrar_estado('CERRADA', 'Cerrada', 907, 'Y');
    sembrar_categoria('MOBILIARIO', 'Mobiliario oraculo cierre', 905);

    SELECT category_id INTO v_cat FROM cat_categoria_incidencia WHERE category_code = 'MOBILIARIO';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA54B' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA54B', 'Oficina Oraculo Cierre', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA54B';

    -- Los usuarios se crean ANTES que la sala porque cat_sala.created_by es NOT NULL.
    -- username, password_hash y password_algorithm son NOT NULL desde 06-usuario-credenciales.xml.
    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES ('Oraculo Cierre Admin', 'oraculo.tsk054.cie.admin@example.invalid',
                 'oraculo.tsk054.cie.admin', 'ADMINISTRADOR', 'ACTIVO',
                 'hash-oraculo-tsk054-cie-admin', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Cierre Empleado', 'oraculo.tsk054.cie.empleado@example.invalid',
                 'oraculo.tsk054.cie.empleado', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk054-cie-empleado', 'argon2id', v_admin)
      RETURNING user_id INTO v_empleado;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Cierre Tecnico', 'oraculo.tsk054.cie.tecnico@example.invalid',
                 'oraculo.tsk054.cie.tecnico', 'TECNICO_MANTENIMIENTO', 'ACTIVO',
                 'hash-oraculo-tsk054-cie-tecnico', 'argon2id', v_admin)
      RETURNING user_id INTO v_tecnico;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA54B' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA54B', 'Sala Oraculo Cierre', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA54B';

    -- (1) Incidencia llevada a RESUELTA con marcas coherentes. created_at va tres horas atras
    --     porque ck_incidencia_cronologia exige que toda marca posterior sea mayor o igual que el
    --     alta, y el inicio de atencion y la resolucion se sellan dos y una hora atras.
    INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by, created_at)
         VALUES ('INC-9054B-000001', v_room, v_cat,
                 'Incidencia del oraculo de cierre que se llevara hasta el estado RESUELTA',
                 v_empleado, v_ahora - INTERVAL '3' HOUR)
      RETURNING incident_id INTO v_inc;

    SELECT version INTO v_version_alta FROM incidencia WHERE incident_id = v_inc;

    UPDATE incidencia
       SET status                 = 'RESUELTA',
           in_progress_at         = v_ahora - INTERVAL '2' HOUR,
           resolved_at            = v_ahora - INTERVAL '1' HOUR,
           assigned_technician_id = v_tecnico,
           assigned_at            = v_ahora - INTERVAL '2' HOUR,
           status_changed_at      = v_ahora - INTERVAL '1' HOUR,
           status_changed_by      = v_tecnico
     WHERE incident_id = v_inc;

    SELECT version INTO v_version_res FROM incidencia WHERE incident_id = v_inc;

    IF v_version_res <= v_version_alta THEN
        RAISE_APPLICATION_ERROR(-20950, 'ORACULO REQ-118 RN-03: la version era ' || v_version_alta ||
            ' en el alta y es ' || v_version_res || ' tras llevar la incidencia a RESUELTA;' ||
            ' el motor tiene que incrementarla en cada UPDATE');
    END IF;

    -- (2) INTENTO A: cierre SIN comentario de resolucion. Debe fallar.
    BEGIN
        UPDATE incidencia
           SET status            = 'CERRADA',
               closed_at         = v_ahora - INTERVAL '30' MINUTE,
               closed_by         = v_tecnico,
               status_changed_at = v_ahora - INTERVAL '30' MINUTE,
               status_changed_by = v_tecnico
         WHERE incident_id = v_inc;
        v_codigo := 0;
    EXCEPTION
        WHEN OTHERS THEN
            v_codigo := SQLCODE;
    END;

    IF v_codigo NOT IN (-20054, -2290) THEN
        RAISE_APPLICATION_ERROR(-20951, 'ORACULO AC-CIE-01: el cierre sin comentario de resolucion' ||
            ' devolvio ' || v_codigo || '; cerrar una incidencia sin comentario de resolucion tiene' ||
            ' que ser IMPOSIBLE en la base de datos, con ORA-20054 (trigger) u ORA-02290 (CHECK)');
    END IF;

    -- (3) INTENTO B: cierre con un comentario que solo contiene espacios y tabuladores.
    --     Es la mitad "no vacio tras TRIM" de AC-CIE-02: un texto en blanco no es un comentario.
    BEGIN
        UPDATE incidencia
           SET status             = 'CERRADA',
               closed_at          = v_ahora - INTERVAL '30' MINUTE,
               closed_by          = v_tecnico,
               resolution_comment = '   ' || CHR(9) || '  ' || CHR(9) || ' ',
               status_changed_at  = v_ahora - INTERVAL '30' MINUTE,
               status_changed_by  = v_tecnico
         WHERE incident_id = v_inc;
        v_codigo := 0;
    EXCEPTION
        WHEN OTHERS THEN
            v_codigo := SQLCODE;
    END;

    IF v_codigo NOT IN (-20054, -2290) THEN
        RAISE_APPLICATION_ERROR(-20952, 'ORACULO AC-CIE-02: el cierre con un comentario de solo' ||
            ' espacios y tabuladores devolvio ' || v_codigo || '; un comentario vacio tras TRIM no' ||
            ' es un comentario de resolucion y el motor tiene que rechazarlo con ORA-20054 u ORA-02290');
    END IF;

    -- (4) Tras los dos rechazos la fila tiene que seguir EXACTAMENTE como estaba: ni medio cierre,
    --     ni una marca suelta, ni el nombre virtual del cerrador informado.
    SELECT status, closed_at, closed_by, closed_by_user_id, resolution_comment
      INTO v_status, v_closed_at, v_closed_by, v_closed_virt, v_comentario
      FROM incidencia
     WHERE incident_id = v_inc;

    IF v_status <> 'RESUELTA'
       OR v_closed_at IS NOT NULL
       OR v_closed_by IS NOT NULL
       OR v_closed_virt IS NOT NULL
       OR v_comentario IS NOT NULL THEN
        RAISE_APPLICATION_ERROR(-20953, 'ORACULO AC-CIE-02: un cierre rechazado no deja ningun dato' ||
            ' de cierre informado, y la incidencia quedo en estado ' || v_status ||
            ' con closed_at=' || NVL(TO_CHAR(v_closed_at), 'NULL') ||
            ', closed_by=' || NVL(TO_CHAR(v_closed_by), 'NULL') ||
            ', closed_by_user_id=' || NVL(TO_CHAR(v_closed_virt), 'NULL') ||
            ', resolution_comment=' || CASE WHEN v_comentario IS NULL THEN 'NULL' ELSE 'INFORMADO' END);
    END IF;

    -- (5) Cierre VALIDO: la misma sentencia con un comentario de resolucion real tiene que pasar.
    UPDATE incidencia
       SET status             = 'CERRADA',
           closed_at          = v_ahora - INTERVAL '30' MINUTE,
           closed_by          = v_tecnico,
           resolution_comment = 'Se ha sustituido el mecanismo averiado de la mesa y se ha' ||
                                ' verificado su funcionamiento con la persona que reporto la incidencia.',
           status_changed_at  = v_ahora - INTERVAL '30' MINUTE,
           status_changed_by  = v_tecnico
     WHERE incident_id = v_inc;

    SELECT status, closed_at, closed_by, closed_by_user_id, resolution_comment, resolved_at,
           NVL(REGEXP_INSTR(resolution_comment, '[^[:space:]]'), 0)
      INTO v_status, v_closed_at, v_closed_by, v_closed_virt, v_comentario, v_resolved_at, v_util
      FROM incidencia
     WHERE incident_id = v_inc;

    IF v_status <> 'CERRADA'
       OR v_closed_at IS NULL
       OR v_closed_by IS NULL
       OR v_closed_by <> v_tecnico
       OR v_closed_virt IS NULL
       OR v_closed_virt <> v_closed_by
       OR v_comentario IS NULL
       OR v_util = 0
       OR v_closed_at < v_resolved_at THEN
        RAISE_APPLICATION_ERROR(-20954, 'ORACULO AC-CIE-01: el cierre valido no dejo la fila' ||
            ' completa: status=' || v_status ||
            ', closed_at=' || NVL(TO_CHAR(v_closed_at), 'NULL') ||
            ', closed_by=' || NVL(TO_CHAR(v_closed_by), 'NULL') ||
            ' (tecnico esperado ' || v_tecnico || ')' ||
            ', closed_by_user_id=' || NVL(TO_CHAR(v_closed_virt), 'NULL') ||
            ', caracteres utiles del comentario=' || v_util ||
            ', resolved_at=' || NVL(TO_CHAR(v_resolved_at), 'NULL'));
    END IF;

    -- (6) INTENTO C sobre OTRA incidencia: cierre incompleto. El comentario esta, pero faltan
    --     closed_at y closed_by, y los cuatro datos de cierre son un bloque atomico (REQ-111 RN-04).
    INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by, created_at)
         VALUES ('INC-9054B-000002', v_room, v_cat,
                 'Segunda incidencia del oraculo de cierre para el intento de cierre incompleto',
                 v_empleado, v_ahora - INTERVAL '3' HOUR)
      RETURNING incident_id INTO v_inc_c;

    UPDATE incidencia
       SET status                 = 'RESUELTA',
           in_progress_at         = v_ahora - INTERVAL '2' HOUR,
           resolved_at            = v_ahora - INTERVAL '1' HOUR,
           assigned_technician_id = v_tecnico,
           assigned_at            = v_ahora - INTERVAL '2' HOUR,
           status_changed_at      = v_ahora - INTERVAL '1' HOUR,
           status_changed_by      = v_tecnico
     WHERE incident_id = v_inc_c;

    BEGIN
        UPDATE incidencia
           SET status             = 'CERRADA',
               resolution_comment = 'Se da por cerrada la incidencia sin informar ni la fecha ni el autor del cierre.',
               status_changed_at  = v_ahora - INTERVAL '30' MINUTE,
               status_changed_by  = v_tecnico
         WHERE incident_id = v_inc_c;
        v_codigo := 0;
    EXCEPTION
        WHEN OTHERS THEN
            v_codigo := SQLCODE;
    END;

    IF v_codigo NOT IN (-2290, -20054, -20055) THEN
        RAISE_APPLICATION_ERROR(-20955, 'ORACULO AC-CIE-02 / REQ-111 RN-04: un cierre sin closed_at' ||
            ' ni closed_by devolvio ' || v_codigo || '; los cuatro datos de cierre (estado, fecha,' ||
            ' autor y comentario de resolucion) coexisten obligatoriamente, y ck_incidencia_cierre_coexiste' ||
            ' tiene que rechazar la escritura con ORA-02290');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin        NUMBER;
    v_empleado     NUMBER;
    v_tecnico      NUMBER;
    v_office       NUMBER;
    v_room         NUMBER;
    v_cat          NUMBER;
    v_inc          NUMBER;
    v_inc_vigente  NUMBER;
    v_codigo       NUMBER;
    v_filas        NUMBER;
    v_cerradas     NUMBER;
    v_antes        NUMBER;
    v_despues      NUMBER;
    v_status       incidencia.status%TYPE;
    v_room_leida   incidencia.room_id%TYPE;
    v_cat_leida    incidencia.category_id%TYPE;
    v_tec_leido    incidencia.assigned_technician_id%TYPE;
    v_creada       incidencia.created_at%TYPE;
    v_cerrada_en   incidencia.closed_at%TYPE;
    v_retencion    DATE;
    v_esperada     DATE;
    v_desde_cierre DATE;
    v_ahora        TIMESTAMP(6) := SYS_EXTRACT_UTC(SYSTIMESTAMP);

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;

    -- Variante del sembrador de estados con el flag is_terminal: el escenario recorre el ciclo
    -- completo y necesita CERRADA, que es el unico estado terminal del catalogo.
    PROCEDURE sembrar_estado(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER,
                             p_terminal VARCHAR2 DEFAULT 'N') IS
    BEGIN
        MERGE INTO cat_estado_incidencia d
        USING (SELECT p_code AS status_code FROM dual) s
           ON (d.status_code = s.status_code)
        WHEN NOT MATCHED THEN
            INSERT (status_code, status_name, sort_order, is_terminal, is_active)
            VALUES (p_code, p_name, p_order, p_terminal, 'Y');
    END sembrar_estado;

    PROCEDURE sembrar_categoria(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_categoria_incidencia d
        USING (SELECT p_code AS category_code FROM dual) s
           ON (d.category_code = s.category_code)
        WHEN NOT MATCHED THEN
            INSERT (category_code, category_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');

        -- La categoria tiene que estar ACTIVA aunque la fila ya existiese: el trigger
        -- trg_incidencia_clasificacion rechaza el alta sobre catalogo inactivo (REQ-100).
        UPDATE cat_categoria_incidencia SET is_active = 'Y' WHERE category_code = p_code;
    END sembrar_categoria;

BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 911);
    sembrar_rol('TECNICO_MANTENIMIENTO', 'Tecnico de mantenimiento', 912);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 913);
    sembrar_estado('ABIERTA', 'Abierta', 911, 'N');
    sembrar_estado('EN_CURSO', 'En curso', 912, 'N');
    sembrar_estado('RESUELTA', 'Resuelta', 913, 'N');
    sembrar_estado('CERRADA', 'Cerrada', 914, 'Y');
    sembrar_categoria('CLIMATIZACION', 'Climatizacion oraculo retencion', 911);

    SELECT category_id INTO v_cat FROM cat_categoria_incidencia WHERE category_code = 'CLIMATIZACION';

    MERGE INTO cat_oficina d
    USING (SELECT 'OF-ORA54C' AS office_code FROM dual) s
       ON (d.office_code = s.office_code)
    WHEN NOT MATCHED THEN
        INSERT (office_code, office_name, city, is_active)
        VALUES ('OF-ORA54C', 'Oficina Oraculo Retencion', 'Madrid', 'Y');
    SELECT office_id INTO v_office FROM cat_oficina WHERE office_code = 'OF-ORA54C';

    -- Los usuarios se crean ANTES que la sala porque cat_sala.created_by es NOT NULL.
    -- username, password_hash y password_algorithm son NOT NULL desde 06-usuario-credenciales.xml.
    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm)
         VALUES ('Oraculo Retencion Admin', 'oraculo.tsk054.ret.admin@example.invalid',
                 'oraculo.tsk054.ret.admin', 'ADMINISTRADOR', 'ACTIVO',
                 'hash-oraculo-tsk054-ret-admin', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Retencion Empleado', 'oraculo.tsk054.ret.empleado@example.invalid',
                 'oraculo.tsk054.ret.empleado', 'EMPLEADO', 'ACTIVO',
                 'hash-oraculo-tsk054-ret-empleado', 'argon2id', v_admin)
      RETURNING user_id INTO v_empleado;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, status,
                         password_hash, password_algorithm, created_by)
         VALUES ('Oraculo Retencion Tecnico', 'oraculo.tsk054.ret.tecnico@example.invalid',
                 'oraculo.tsk054.ret.tecnico', 'TECNICO_MANTENIMIENTO', 'ACTIVO',
                 'hash-oraculo-tsk054-ret-tecnico', 'argon2id', v_admin)
      RETURNING user_id INTO v_tecnico;

    MERGE INTO cat_sala d
    USING (SELECT 'SAL-ORA54C' AS room_code FROM dual) s
       ON (d.room_code = s.room_code)
    WHEN NOT MATCHED THEN
        INSERT (room_code, room_name, office_id, is_active, created_by)
        VALUES ('SAL-ORA54C', 'Sala Oraculo Retencion', v_office, 'Y', v_admin);
    SELECT room_id INTO v_room FROM cat_sala WHERE room_code = 'SAL-ORA54C';

    -- (1) Alta hace 13 meses y ciclo de vida completo hasta CERRADA hace 30 dias.
    INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by, created_at)
         VALUES ('INC-9054C-000001', v_room, v_cat,
                 'Incidencia antigua del oraculo de retencion, cerrada hace treinta dias',
                 v_empleado, v_ahora - INTERVAL '395' DAY)
      RETURNING incident_id INTO v_inc;

    UPDATE incidencia
       SET status                 = 'EN_CURSO',
           assigned_technician_id = v_tecnico,
           assigned_at            = v_ahora - INTERVAL '61' DAY,
           in_progress_at         = v_ahora - INTERVAL '60' DAY,
           status_changed_at      = v_ahora - INTERVAL '60' DAY,
           status_changed_by      = v_tecnico
     WHERE incident_id = v_inc;

    UPDATE incidencia
       SET status            = 'RESUELTA',
           resolved_at       = v_ahora - INTERVAL '31' DAY,
           status_changed_at = v_ahora - INTERVAL '31' DAY,
           status_changed_by = v_tecnico
     WHERE incident_id = v_inc;

    UPDATE incidencia
       SET status             = 'CERRADA',
           closed_at          = v_ahora - INTERVAL '30' DAY,
           closed_by          = v_tecnico,
           resolution_comment = 'Se reparo la unidad de climatizacion de la sala y se confirmo la' ||
                                ' temperatura correcta antes de cerrar la incidencia.',
           status_changed_at  = v_ahora - INTERVAL '30' DAY,
           status_changed_by  = v_tecnico
     WHERE incident_id = v_inc;

    -- (2) AC-RET-01: la incidencia cerrada SIGUE en la tabla operativa y se encuentra con el
    --     filtro de la bandeja (estado + sala + categoria), con todos sus datos intactos.
    SELECT COUNT(*)
      INTO v_filas
      FROM incidencia
     WHERE status = 'CERRADA'
       AND room_id = v_room
       AND category_id = v_cat;

    SELECT status, room_id, category_id, closed_at, assigned_technician_id, created_at
      INTO v_status, v_room_leida, v_cat_leida, v_cerrada_en, v_tec_leido, v_creada
      FROM incidencia
     WHERE incident_id = v_inc;

    IF v_filas <> 1
       OR v_status <> 'CERRADA'
       OR v_room_leida IS NULL
       OR v_cat_leida IS NULL
       OR v_cerrada_en IS NULL
       OR v_tec_leido IS NULL THEN
        RAISE_APPLICATION_ERROR(-20960, 'ORACULO AC-RET-01: el cierre no archiva ni mueve la' ||
            ' incidencia, pero la consulta por estado, sala y categoria devolvio ' || v_filas ||
            ' filas y la fila leida tiene status=' || NVL(v_status, 'NULL') ||
            ', room_id=' || NVL(TO_CHAR(v_room_leida), 'NULL') ||
            ', category_id=' || NVL(TO_CHAR(v_cat_leida), 'NULL') ||
            ', closed_at=' || NVL(TO_CHAR(v_cerrada_en), 'NULL') ||
            ', assigned_technician_id=' || NVL(TO_CHAR(v_tec_leido), 'NULL'));
    END IF;

    -- (3) AC-RET-02: una consulta que NO fija el estado devuelve la cerrada junto a la vigente.
    INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by)
         VALUES ('INC-9054C-000002', v_room, v_cat,
                 'Incidencia vigente de la misma sala para comprobar que la cerrada sigue listandose',
                 v_empleado)
      RETURNING incident_id INTO v_inc_vigente;

    SELECT COUNT(*) INTO v_filas FROM incidencia WHERE room_id = v_room;
    SELECT COUNT(*) INTO v_cerradas FROM incidencia WHERE room_id = v_room AND incident_id = v_inc;

    IF v_filas <> 2 OR v_cerradas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20961, 'ORACULO AC-RET-02: ningun filtro por defecto excluye los' ||
            ' estados terminales, pero la consulta por sala devolvio ' || v_filas ||
            ' filas en lugar de 2 y la incidencia cerrada aparece ' || v_cerradas || ' veces');
    END IF;

    -- (4) REQ-148 / AC-RET-01: la retencion se cuenta desde el ALTA, no desde el cierre.
    SELECT retention_expires_at,
           CAST(created_at + INTERVAL '24' MONTH AS DATE),
           CAST(closed_at + INTERVAL '24' MONTH AS DATE)
      INTO v_retencion, v_esperada, v_desde_cierre
      FROM incidencia
     WHERE incident_id = v_inc;

    IF v_retencion IS NULL OR v_retencion <> v_esperada THEN
        RAISE_APPLICATION_ERROR(-20962, 'ORACULO REQ-148: retention_expires_at vale ' ||
            NVL(TO_CHAR(v_retencion, 'YYYY-MM-DD'), 'NULL') || ' y tiene que valer ' ||
            TO_CHAR(v_esperada, 'YYYY-MM-DD') || ', es decir 24 meses despues del alta (' ||
            TO_CHAR(v_creada, 'YYYY-MM-DD') || ')');
    END IF;

    IF v_retencion = v_desde_cierre THEN
        RAISE_APPLICATION_ERROR(-20962, 'ORACULO REQ-148: retention_expires_at vale ' ||
            TO_CHAR(v_retencion, 'YYYY-MM-DD') || ', que son 24 meses despues del CIERRE (' ||
            TO_CHAR(v_cerrada_en, 'YYYY-MM-DD') || '); la retencion se cuenta desde el alta');
    END IF;

    SELECT COUNT(*) INTO v_antes FROM incidencia;

    -- (5) AC-TRZ-03 / AC-RET-06: el valor enviado por el cliente no puede sustituir al derivado.
    --     Las dos sentencias van en SQL DINAMICO a proposito: en SQL estatico el bloque entero no
    --     compilaria (el error de columna virtual se da al analizar la sentencia) y el despliegue
    --     moriria en lugar de VERIFICAR el rechazo.
    BEGIN
        EXECUTE IMMEDIATE
            'INSERT INTO incidencia (reference_code, room_id, category_id, description, reported_by,' ||
            ' retention_expires_at) VALUES (:ref, :room, :cat, :descr, :rep, DATE ''2099-12-31'')'
            USING 'INC-9054C-000003', v_room, v_cat,
                  'Alta que intenta fijar la fecha de retencion desde el cliente de la API',
                  v_empleado;
        v_codigo := 0;
    EXCEPTION
        WHEN OTHERS THEN
            v_codigo := SQLCODE;
    END;

    IF v_codigo <> -54013 THEN
        RAISE_APPLICATION_ERROR(-20963, 'ORACULO AC-TRZ-03: un alta que informa retention_expires_at' ||
            ' devolvio ' || v_codigo || ' y tiene que devolver ORA-54013 (operacion no permitida' ||
            ' sobre columna virtual): la fecha de retencion la calcula el motor, no el cliente');
    END IF;

    BEGIN
        EXECUTE IMMEDIATE
            'UPDATE incidencia SET retention_expires_at = DATE ''2099-12-31'' WHERE incident_id = :id'
            USING v_inc;
        v_codigo := 0;
    EXCEPTION
        WHEN OTHERS THEN
            v_codigo := SQLCODE;
    END;

    -- ORA-54013 e ORA-54017 son la misma familia de rechazo sobre columna virtual (la primera la
    -- devuelve el INSERT y la segunda el UPDATE segun version del motor); lo inadmisible es 0.
    IF v_codigo NOT IN (-54013, -54017) THEN
        RAISE_APPLICATION_ERROR(-20964, 'ORACULO AC-RET-06: un UPDATE que escribe' ||
            ' retention_expires_at devolvio ' || v_codigo || ' y tiene que devolver ORA-54013 u' ||
            ' ORA-54017 (operacion no permitida sobre columna virtual)');
    END IF;

    SELECT retention_expires_at
      INTO v_retencion
      FROM incidencia
     WHERE incident_id = v_inc;

    IF v_retencion IS NULL OR v_retencion <> v_esperada THEN
        RAISE_APPLICATION_ERROR(-20965, 'ORACULO AC-TRZ-03: el valor derivado no lo puede sustituir' ||
            ' el cliente, pero tras los dos intentos rechazados retention_expires_at vale ' ||
            NVL(TO_CHAR(v_retencion, 'YYYY-MM-DD'), 'NULL') || ' en lugar de ' ||
            TO_CHAR(v_esperada, 'YYYY-MM-DD'));
    END IF;

    -- (6) Los dos intentos rechazados no han escrito NADA: mismo recuento de filas antes y despues.
    SELECT COUNT(*) INTO v_despues FROM incidencia;

    IF v_despues <> v_antes THEN
        RAISE_APPLICATION_ERROR(-20966, 'ORACULO AC-TRZ-03: la tabla incidencia tenia ' || v_antes ||
            ' filas antes de los intentos rechazados y tiene ' || v_despues ||
            ' despues; una escritura rechazada no puede dejar ninguna fila');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
